from pathlib import Path
p = Path('utils/backgroundImageJobs.ts')
s = p.read_text()
old = """            if (localJob.submitAttempts >= MAX_SUBMIT_ATTEMPTS) {\n                await markMonitoredJobFailed(\n                    localJob.id,\n                    '后台生图任务多次提交失败',\n                    options,\n                );\n                return;\n            }\n\n            const attempted = updateJob(localJob.id, {\n                status: 'submitting',\n                submitAttempts: localJob.submitAttempts + 1,\n                lastCheckedAt: now(),\n            });\n            if (!attempted) return;\n\n            try {\n                remoteJob = await submitRemoteJob(attempted);\n            } catch (error) {\n                if (\n                    isPermanentSubmitError(error)\n                    || isUnsupportedJobsEndpointError(error)\n                ) {\n                    await markMonitoredJobFailed(\n                        localJob.id,\n                        isUnsupportedJobsEndpointError(error)\n                            ? '当前生图服务不支持后台任务接口 /jobs，请更新服务端或重新发起直连生图。'\n                            : error,\n                        options,\n                    );\n                    return;\n                }\n                throw error;\n            }\n"""
new = """            // 只有普通本地任务允许客户端自己 POST。Worker-owned 剧情任务如果上面已经\n            // 通过最终 handoff 找到 remoteJob，就直接进入下面的状态处理，绝不能再走这里。\n            if (!remoteJob) {\n                if (localJob.submitAttempts >= MAX_SUBMIT_ATTEMPTS) {\n                    await markMonitoredJobFailed(\n                        localJob.id,\n                        '后台生图任务多次提交失败',\n                        options,\n                    );\n                    return;\n                }\n\n                const attempted = updateJob(localJob.id, {\n                    status: 'submitting',\n                    submitAttempts: localJob.submitAttempts + 1,\n                    lastCheckedAt: now(),\n                });\n                if (!attempted) return;\n\n                try {\n                    remoteJob = await submitRemoteJob(attempted);\n                } catch (error) {\n                    if (\n                        isPermanentSubmitError(error)\n                        || isUnsupportedJobsEndpointError(error)\n                    ) {\n                        await markMonitoredJobFailed(\n                            localJob.id,\n                            isUnsupportedJobsEndpointError(error)\n                                ? '当前生图服务不支持后台任务接口 /jobs，请更新服务端或重新发起直连生图。'\n                                : error,\n                            options,\n                        );\n                        return;\n                    }\n                    throw error;\n                }\n            }\n"""
assert old in s
s = s.replace(old, new, 1)
p.write_text(s)
